use std::{println, time::Duration};

use slint::ComponentHandle;
use vexide::{math::Angle, prelude::*};
use vexide_motorgroup::MotorGroup;

use crate::{auton::{claw, set_lift}, util::remap_num};

mod util;
mod auton;
mod config;

// Include the modules generated by Slint for your UI files.
// You will need to configure your `build.rs` to do this; see below.
slint::include_modules!();


impl Compete for util::Robot {
    async fn autonomous(&mut self) {
        println!("Autonomous!");
        self.ui.set_status_text("Status: Auton".into());

        auton::track_location(self);
        println!("{}", util::stringify_location(self.loc));

        auton::move_to_loc(self, util::loc(0.0, 0.687, 0.0), 0.2, 5.0).await;
        set_lift(self, 200.0);
        sleep(Duration::from_millis(500)).await;

        claw(self, -12.0, true);
        auton::move_to_loc(self, util::loc(-0.455, 1.083, 0.0), 0.2, 5.0).await;
        sleep(Duration::from_millis(500)).await;
        set_lift(self, 0.0);
        loop { 
            if auton::get_lift(self) >= 5.0 {break}; 
            sleep(Controller::UPDATE_INTERVAL).await;
        }
        set_lift(self, 200.0);
        loop { 
            if auton::get_lift(self) <= 190.0 {break}; 
            sleep(Controller::UPDATE_INTERVAL).await;
        }
        claw(self, 0.0, true);

        auton::move_to_loc(self, util::loc(-0.563, 0.803, 0.0), 0.2, 5.0).await;
        sleep(Duration::from_millis(500)).await;

        set_lift(self, 0.0);
        loop { 
            if auton::get_lift(self) >= 5.0 {break}; 
            sleep(Controller::UPDATE_INTERVAL).await;
        }

        claw(self, 12.0, true);
       
        println!("Auton Complete!");
    }

    async fn driver(&mut self) {
        println!("Driver!");
        self.ui.set_status_text("Status: Driver".into());

        let mut claw_rot_state: f64 = 0.0;
        let mut config_open: bool = false;
        loop {
            let state = self.controller.state().unwrap_or_default();

            // CONTROLS
            let mut c_turn: f64 = 0.0;
            let mut c_throttle: f64 = 0.0;
            let mut c_lift: f64 = 0.0;
            let mut c_intake: f64 = 0.0;
            let mut c_claw: f64 = 0.0;
            let mut c_claw_rot: f64 = -1.0;
            if !config_open {
                c_turn     = state.right_stick.x();
                c_throttle = state.left_stick.y();

                c_lift     = if state.button_l1.is_pressed()      { 1.0 }  // Up
                             else if state.button_l2.is_pressed() {-1.0 }  // Down
                             else                                 { 0.0 }; // Hold

                c_intake   = if state.button_r1.is_pressed()      { 1.0 }  // Intake
                             else if state.button_r2.is_pressed() {-1.0 }  // Outtake
                             else                                 { 0.0 }; // Hold

                c_claw     = if state.button_r1.is_pressed()      { 1.0 }  // Intake
                             else if state.button_r2.is_pressed() {-1.0 }  // Outtake
                             else                                 { 0.0 }; // Hold

                c_claw_rot = if state.button_a. is_pressed()      { 1.0 }  // Up
                             else if state.button_b. is_pressed() { 0.1 }  // Down
                             else                                 {-1.0 }; // Hold
            }

            // CONFIG CONTROLS
            if state.button_x.is_pressed() && state.button_up.is_now_pressed() { 
                config_open = ! config_open;
                if !config_open { _ = self.controller.clear_screen().await; }
            }

            if config_open {
                // _ = self.controller.clear_screen().await;
                if state.button_down.is_pressed() || state.button_up.is_pressed() || state.button_left.is_pressed() || state.button_right.is_pressed() || state.button_x.is_pressed() {
                    config::draw_config(&mut self.controller, self.config.clone()).await;
                }
                self.config.current_row = if state.button_down.is_now_pressed()    { (self.config.current_row + 1).clamp(1, self.config.number_configs.len() as isize-1) }
                                          else if state.button_up.is_now_pressed() { (self.config.current_row - 1).clamp(0, self.config.number_configs.len() as isize-2) }
                                          else                                     { self.config.current_row };
                
                if state.button_left.is_now_pressed() {
                    let option: &mut config::ConfigNumber = &mut self.config.number_configs[self.config.current_row as usize];
                    option.value -= if state.button_x.is_pressed() { option.increment * option.increment } else { option.increment };
                    option.value = option.value.clamp(option.min_value, option.max_value);
                }

                if state.button_right.is_now_pressed() {
                    let option: &mut config::ConfigNumber = &mut self.config.number_configs[self.config.current_row as usize];
                    option.value += if state.button_x.is_pressed() { option.increment * option.increment } else { option.increment };
                    option.value = option.value.clamp(option.min_value, option.max_value);
                }
            }

            // READ CONFIG
            let drive_speed     = self.config.number_configs[0].value;
            let turn_speed      = self.config.number_configs[1].value;
            let claw_low_angle  = self.config.number_configs[2].value;
            let claw_high_angle = self.config.number_configs[3].value;

            // DRIVING
            let l = c_throttle + util::steering(c_turn) * util::turn_speed(c_turn) * turn_speed;
            let r = c_throttle - util::steering(c_turn) * util::turn_speed(c_turn) * turn_speed;

            _ = self.left_motors.set_voltage(l * self.left_motors.max_voltage() * drive_speed);
            _ = self.right_motors.set_voltage(r * self.left_motors.max_voltage() * drive_speed);

            // LIFT
            _ = self.lift_motors.set_voltage(c_lift * self.lift_motors.max_voltage());
            if self.lift_motors.position().unwrap_or(Angle::ZERO).as_degrees() < 0.0 {
                _ = self.lift_motors.set_voltage(self.lift_motors.max_voltage());
            }

            // INTAKE
            _ = self.intake_motor.set_voltage(-c_intake * self.lift_motors.max_voltage());

            // CLAW
            _ = self.claw_motor.set_voltage(-c_claw * self.lift_motors.max_voltage());

            // CLAW ROTATION
            if c_claw_rot != -1.0 { claw_rot_state = c_claw_rot }
            _ = self.claw_tilt.set_position_target(Angle::from_degrees(remap_num(claw_rot_state, -claw_low_angle, claw_high_angle)), 200);

            sleep(Controller::UPDATE_INTERVAL).await; 
        }
    }
}

#[vexide::main(banner(enabled = false))]
async fn main(peripherals: vexide::prelude::Peripherals) {
    let controller = peripherals.primary_controller;

    let left_motors = MotorGroup::new(vec![
        Motor::new(peripherals.port_8, Gearset::Green, Direction::Reverse),
        Motor::new(peripherals.port_15, Gearset::Green, Direction::Reverse)
    ]);
    let right_motors = MotorGroup::new(vec![
        Motor::new(peripherals.port_18, Gearset::Green, Direction::Forward),
        Motor::new(peripherals.port_13, Gearset::Green, Direction::Forward)
    ]);

    let mut imu = InertialSensor::new(peripherals.port_3);
    _ = imu.calibrate().await;

    let lift_motors = MotorGroup::new(vec![
        Motor::new(peripherals.port_2, Gearset::Green, Direction::Forward),
        Motor::new(peripherals.port_6, Gearset::Green, Direction::Reverse)
    ]);
    let claw_motor = Motor::new_exp(peripherals.port_5, Direction::Forward);
    let claw_tilt = Motor::new_exp(peripherals.port_4, Direction::Forward);
    let intake_motor = Motor::new(peripherals.port_10, Gearset::Green, Direction::Forward);

    // Initialize the Slint platform with the V5 display-backed implementation.
    vexide_slint::initialize_slint_platform(peripherals.display);
    let ui: App = App::new()
        .expect("Failed to create application");

    let robot = util::Robot {
        controller,
        left_motors,
        right_motors,
        imu,
        claw_motor,
        claw_tilt,
        lift_motors,
        ui: ui.clone_strong(),
        intake_motor,

        loc: util::loc(0.0, 0.0, 0.0),
        config: config::default_config()
    };

    // Run vex code in a seperate thread
    vexide::task::spawn(robot.compete()).detach();

    ui.run().expect("Failed to run application");

}